describe('Color.convert', () => {
  let colorInstance;

  beforeEach(() => {
    colorInstance = new Color();
  });

  test('should return black color if target color space is invalid', () => {
    const colorArray = ["RGB", 1, 0, 0];
    const invalidColorSpace = "INVALID_SPACE";

    const result = colorInstance.convert(colorArray, invalidColorSpace);

    expect(result).toEqual(colorInstance.black);
  });

  test('should return transparent color for transparency input', () => {
    const colorArray = ["T"];
    const targetColorSpace = "RGB";

    const result = colorInstance.convert(colorArray, targetColorSpace);

    expect(result).toEqual(colorInstance.transparent);
  });

  test('should return the same color if already in the target color space', () => {
    const colorArray = ["RGB", 1, 0, 0];
    const targetColorSpace = "RGB";

    const result = colorInstance.convert(colorArray, targetColorSpace);

    expect(result).toEqual(colorArray);
  });

  test('should convert color using ColorConverters when valid source and target color spaces are provided', () => {
    const colorArray = ["RGB", 1, 0, 0];
    const targetColorSpace = "CMYK";

    // Mock the ColorConverters function
    jest.spyOn(ColorConverters, 'convertRGBToCMYK').mockReturnValue(["CMYK", 0, 1, 1, 0]);

    const result = colorInstance.convert(colorArray, targetColorSpace);

    expect(ColorConverters.convertRGBToCMYK).toHaveBeenCalledWith(1, 0, 0);
    expect(result).toEqual(["CMYK", 0, 1, 1, 0]);

    // Restore the original implementation
    jest.restoreAllMocks();
  });

  test('should throw TypeError if colorArray is not an array', () => {
